const money=n=>'₹'+n.toLocaleString('en-IN');const visual=(p)=>p.photo?`<img loading="lazy" src="https://images.unsplash.com/${p.photo}?auto=format&fit=crop&w=700&q=80" alt="${p.name}, reference photography">`:`<div class="garment" style="--slot:${p.slot}" role="img" aria-label="${p.name} on a hanger"></div>`;let filter='All',query='',selected=0,cart=[];try{cart=JSON.parse(localStorage.getItem('shades-showroom-bag')||'[]').filter(x=>products[x.id]&&['S','M','L','XL','XXL'].includes(x.size)&&products[x.id].colors.includes(x.color)&&Number.isInteger(x.qty)&&x.qty>0)}catch{}const pm=document.querySelector('#product-modal'),cm=document.querySelector('#cart-modal'),am=document.querySelector('#account-modal');
const rack=document.querySelector('#rack');rack.innerHTML=products.slice(0,5).map((p,i)=>`<button class="hanger" data-hanger="${i}" aria-label="Explore ${p.name}" aria-pressed="false"><div class="garment" style="--slot:${p.slot}"></div><span class="hanger-name">${p.category==='Tailoring'?'Tailoring':p.category==='Trousers'?'Trousers':i===0?'The jacket':i===4?'The coat':'The shirt'}</span></button>`).join('');
function focusGarment(i){selected=i;rack.classList.add('has-selection');document.querySelectorAll('[data-hanger]').forEach(b=>{const yes=+b.dataset.hanger===i;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});const p=products[i];document.querySelector('#spot-details').innerHTML=`<div><span class="eyebrow">THE STUDIO SELECTION</span><h3>${p.name}</h3><p>${p.desc}</p></div><span class="detail-price">${money(p.price)}</span><div class="variants"><div class="swatches" aria-label="Colors: ${p.colors.join(', ')}">${p.swatches.map((c,j)=>`<span class="swatch" style="background:${c}" title="${p.colors[j]}"></span>`).join('')}</div><span class="size-label">S / M / L / XL / XXL</span></div><button class="button dark" id="view-selected">View Product</button>`;document.querySelector('#view-selected').onclick=()=>openProduct(i)}document.querySelectorAll('[data-hanger]').forEach(b=>{b.onpointerenter=e=>{if(e.pointerType==='mouse')focusGarment(+b.dataset.hanger)};b.onfocus=()=>focusGarment(+b.dataset.hanger);b.onclick=()=>focusGarment(+b.dataset.hanger)});focusGarment(1);
const categories=['All','Outerwear','Shirts','Trousers','Tailoring','Polos'];document.querySelector('#filters').innerHTML=categories.map(c=>`<button data-filter="${c}" class="${c==='All'?'active':''}" aria-pressed="${c==='All'}">${c==='All'?'All pieces':c}</button>`).join('');function render(){const matches=products.map((p,i)=>({p,i})).filter(({p})=>(filter==='All'||p.category===filter)&&`${p.name} ${p.category} ${p.color}`.toLowerCase().includes(query));document.querySelector('#products').innerHTML=matches.length?matches.map(({p,i})=>`<button class="product" data-product="${i}"><div class="product-visual">${visual(p)}<span class="product-tag">${i<5?'STUDIO EDIT':'NEW ARRIVAL'}</span><span class="product-plus" aria-hidden="true">＋</span></div><h3>${p.name}</h3><div class="product-meta"><span>${p.color}</span><span>${money(p.price)}</span></div></button>`).join(''):'<p class="no-results">No pieces found. Try another search or category.</p>';document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(+b.dataset.product));document.querySelector('.catalog-count').textContent=`${matches.length} considered pieces`;}function setFilter(c){filter=c;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===c);b.setAttribute('aria-pressed',String(b.dataset.filter===c))});render()}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));document.querySelectorAll('[data-category]').forEach(a=>a.onclick=()=>{query='';document.querySelector('#search').value='';setFilter(a.dataset.category)});document.querySelector('#search').oninput=e=>{query=e.target.value.trim().toLowerCase();render()};document.querySelector('#search-open').onclick=()=>{document.querySelector('#arrivals').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#search').focus({preventScroll:true})};render();
function notify(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}function save(){try{localStorage.setItem('shades-showroom-bag',JSON.stringify(cart))}catch{}document.querySelector('#count').textContent=cart.reduce((s,x)=>s+x.qty,0)}save();function openProduct(i){const p=products[i];document.querySelector('#product-detail').innerHTML=`<div class="product-visual">${visual(p)}</div><div><span class="eyebrow">${p.category.toUpperCase()} / SAMPLE COLLECTION</span><h2>${p.name}</h2><p>${money(p.price)}</p><p>${p.desc}</p><label for="color">Color</label><select id="color">${p.colors.map(c=>`<option>${c}</option>`).join('')}</select><label for="size">Size</label><select id="size"><option value="">Choose your size</option>${['S','M','L','XL','XXL'].map(s=>`<option>${s}</option>`).join('')}</select><button class="button dark" id="add">Add to bag</button><p class="sample-note">Sample design and price. Imagery illustrates the style; exact color and fabric may vary. Live inventory is not connected.</p></div>`;pm.showModal();document.querySelector('#add').onclick=()=>{const size=document.querySelector('#size').value,color=document.querySelector('#color').value;if(!size){document.querySelector('#size').focus();notify('Choose a size to add this piece.');return}const x=cart.find(x=>x.id===i&&x.size===size&&x.color===color);if(x)x.qty++;else cart.push({id:i,size,color,qty:1});save();pm.close();notify('Added to your bag.')}}
function renderCart(){document.querySelector('#cart-items').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-row"><div class="product-visual">${visual(products[x.id])}</div><div>${products[x.id].name}<p>${x.color} / ${x.size} · ${money(products[x.id].price)}</p><button data-qty="${i}" data-change="-1" aria-label="Decrease quantity">−</button>${x.qty}<button data-qty="${i}" data-change="1" aria-label="Increase quantity">＋</button></div><button data-remove="${i}" aria-label="Remove ${products[x.id].name}">×</button></div>`).join(''):'<p>Your bag is waiting for its first considered piece.</p>';document.querySelector('#cart-total').textContent='Subtotal '+money(cart.reduce((s,x)=>s+products[x.id].price*x.qty,0));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);save();renderCart()});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const i=+b.dataset.qty;cart[i].qty+=+b.dataset.change;if(cart[i].qty<1)cart.splice(i,1);save();renderCart()})}function openBag(){renderCart();cm.showModal()}document.querySelector('#bag').onclick=openBag;document.querySelector('#continue').onclick=()=>cm.close();document.querySelector('#account-open').onclick=()=>am.showModal();document.querySelector('#account-bag').onclick=()=>{am.close();openBag()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});document.querySelector('#newsletter').onsubmit=e=>{e.preventDefault();const email=document.querySelector('#email').value;try{localStorage.setItem('shades-newsletter-preview',email);document.querySelector('#newsletter-status').textContent='Preference saved on this device. Email delivery will begin only after the store connects its mailing list.'}catch{document.querySelector('#newsletter-status').textContent='This browser could not save your preference. Please try again with local storage enabled.'}};document.querySelector('#year').textContent=new Date().getFullYear();const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.collection-cards,.editorial-copy,.philosophy-bottom,.newsletter').forEach(el=>{el.classList.add('reveal');observer.observe(el)});
